mapper.select:
SELECT * FROM notification_delivery
WHERE enterprise_id = #{enterprise} AND id = #{id}
FOR UPDATE

mapper.update:
UPDATE notification_delivery d
SET d.status = CASE WHEN EXISTS (
    SELECT 1 FROM notification_delivery_attempt a
    WHERE a.enterprise_id = d.enterprise_id AND a.delivery_id = d.id AND a.outcome IN ('unknown', 'started')
) THEN 'unknown' ELSE 'cancelled' END,
    d.next_attempt_at = NULL, d.last_error_code = 'CHANNEL_CANCELLED',
    d.last_error_summary = CASE WHEN d.status = 'unknown'
        THEN '接收设置或接入已变化，后续发送已停止；此前请求可能已被平台接受。'
        ELSE '接收设置或接入已变化，后续发送已停止。' END,
    d.revision = d.revision + 1, d.updated_at = #{now}
WHERE d.enterprise_id = #{enterprise} AND d.status IN ('pending', 'retry_wait')
AND d.connection_id = #{connection}
AND d.binding_id = #{binding}
AND d.recipient_user_id = #{user}

    AND EXISTS (SELECT 1 FROM notification n WHERE n.enterprise_id = d.enterprise_id
        AND n.id = d.notification_id AND n.source_occurrence_id = #{occurrence})


    AND d.delivery_reason = 'automatic' AND EXISTS (
        SELECT 1 FROM notification n WHERE n.enterprise_id = d.enterprise_id
        AND n.id = d.notification_id AND n.category = #{category}
    )
